def running_mean(values):
    """Return the mean of each prefix of values."""
    means = []
    total = 0.0
    for count, value in enumerate(values, start=1):
        total += value
        means.append(total / count)
    return means


if __name__ == "__main__":
    print(running_mean([2.0, 4.0, 6.0, 8.0]))
